package android.view; import java.util.*; public class ViewGroup extends View { final List<View> children=new ArrayList<>(); final ViewTreeObserver observer=new ViewTreeObserver(); public void addView(View v){v.parent=this;children.add(v);} public int getChildCount(){return children.size();} public View getChildAt(int i){return children.get(i);} public ViewTreeObserver getViewTreeObserver(){return observer;} }